package com.choco.catalog.application.port;

/**
 * Outbound port for product-image storage.
 *
 * <p>The domain and application layers know only that bytes can be stored under a generated key and
 * read back by that key. They do not know whether the bytes live on a local volume or in an object
 * store, which is what allows the storage backend to change without touching a use case.
 *
 * <p>The key is always generated by the implementation, never supplied by a caller. A key derived from
 * an uploaded file name would let a caller choose where their content lands, and a caller who can pick
 * a key can overwrite another product's image.
 */
public interface ImageStoragePort {

    /**
     * Stores the content and returns the generated key.
     *
     * @param productId the owning product, used to group objects and to scope deletion
     * @param contentType the validated image type
     * @param content the bytes
     * @return the generated storage key
     */
    String store(java.util.UUID productId, String contentType, byte[] content);

    /** Reads stored content back, for serving it to a browser. */
    StoredImage read(String storageKey);

    /** Deletes stored content. Idempotent: removing an already-absent key is not an error. */
    void delete(String storageKey);

    /** A stored object and the type to serve it as. */
    record StoredImage(byte[] content, String contentType) {
    }
}
